10	// updateTableSize adjusts table dimensions.
11	//
12	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so only
13	// the table's own header row is subtracted. The Rule 116 arithmetic, the
14	// selected row's width and the cursor clamp are the component's now.
15	func (m *Model) updateTableSize() {
16		m.table.Resize(m.width, max(m.height-1, 1))
17	}
18	
19	// setEntries replaces the listing and rebuilds the decoration over it.
20	//
21	// A new listing is a new population, so the columns are measured again: this is
22	// the directory changing under the user, not a refresh of the same one.
23	func (m *Model) setEntries(entries []Entry) {
24		m.table.SetItems(m.rowsFor(entries))
25		m.table.Remeasure()
26	}
27	
28	// refreshRows redecorates the entries the table already holds. Callers reach it
29	// after a scan starts, finishes or arrives from the cache: the listing has not
30	// changed, only what the six scan columns say about it.
31	//
32	// It deliberately does not go through setEntries any more. A spinner frame
33	// arrives several times a second, and remeasuring on those would let the
34	// columns shift while a scan runs — which is the one thing the measurement is
35	// not allowed to cause.
36	func (m *Model) refreshRows() {
37		m.table.SetItems(m.rowsFor(m.entries()))
38	}
39	
40	// entries returns the current directory listing, filter or no filter.
41	func (m Model) entries() []Entry {
42		out := make([]Entry, 0, len(m.table.Items()))
43		for _, row := range m.table.Items() {
44			out = append(out, row.Entry)
45		}
46		return out
47	}
48	
49	// selectedEntry returns the entry under the cursor.
50	//
51	// Every action used to index the *unfiltered* list with a cursor into the
52	// filtered rows, so under a filter they acted on a different directory from the
53	// one highlighted, and ctrl+d asked to delete it (D24). The table resolves the
54	// cursor against the slice its rows were built from, so the two cannot part.
55	func (m Model) selectedEntry() (Entry, bool) {
56		row, ok := m.table.Selected()
57		return row.Entry, ok
58	}
59	
60	// loadEntries loads the contents of the current directory with enriched metadata
61	func (m Model) loadEntries() tea.Cmd {
62		currentPath := m.currentPath
63		workspacesDir := m.getExpandedWorkspacesDir()
64		// Copied here rather than read inside the closure: a Cmd runs on its own
65		// goroutine and must not touch the model (Rule 110).
66		showHidden := m.config.App.ShowHiddenFiles
67	
68		return func() tea.Msg {
69			targetDir := workspacesDir
70			if currentPath != "" {
71				targetDir = currentPath
72			}
73	
74			// Check if directory exists, create it if it doesn't (only for workspaces root)
75			if _, err := os.Stat(targetDir); os.IsNotExist(err) {
76				if currentPath == "" {
77					if err := os.MkdirAll(targetDir, 0755); err != nil {
78						return LoadErrorMsg{Path: currentPath, Error: err}
79					}
80					return EntriesLoadedMsg{Path: currentPath}
81				}
82				return LoadErrorMsg{Path: currentPath, Error: err}
83			}
84	
85			dirEntries, err := os.ReadDir(targetDir)
86			if err != nil {
87				return LoadErrorMsg{Path: currentPath, Error: err}
88			}
89	
90			entries := make([]Entry, 0, len(dirEntries))
91			for _, dirEntry := range dirEntries {
92				if isHidden(dirEntry.Name(), showHidden) {
93					continue
94				}
95	
96				info, err := dirEntry.Info()
97				if err != nil {
98					continue
99				}
100	
101				path := filepath.Join(targetDir, dirEntry.Name())
102				entry := Entry{
103					Name:    dirEntry.Name(),
104					Path:    path,
105					ModTime: info.ModTime(),
106					// leadsToDir rather than dirEntry.IsDir(): a junction or a
107					// symbolic link to a directory rendered as a file, so the row
108					// was neither browsable nor scannable while the tree behind it
109					// was perfectly ordinary (§1.3 D59). The listing and the
110					// nested-repo walk have to answer this the same way, for the
111					// reason isHidden is shared — two rules would let a directory
112					// be an invisible row and a live scan target at once.
113					IsDir: leadsToDir(dirEntry, path),
114				}
115	
116				// Enrich directory entries with git and project type info
117				if entry.IsDir {
118					enrichEntry(&entry, showHidden)
119				}
120	
121				entries = append(entries, entry)
122			}
123	
124			return EntriesLoadedMsg{Path: currentPath, Entries: entries}
125		}
126	}
