28	// NewWorkspaceInput creates a new workspace input form for directory creation
29	func NewWorkspaceInput() *WorkspaceInput {
30		ti := textinput.New()
31		ti.Placeholder = "directory-name"
32		ti.Focus()
33		ti.CharLimit = 100
34		ti.Width = 40
35		theme.StyleTextInput(&ti)
36	
37		return &WorkspaceInput{
38			input:      ti,
39			focusIndex: focusInput,
40			title:      "New Directory",
41			isRename:   false,
42		}
