45	// NewRenameInput creates a new workspace input form for renaming, pre-filled with the current name
46	func NewRenameInput(currentName string) *WorkspaceInput {
47		ti := textinput.New()
48		ti.Placeholder = "new-name"
49		ti.SetValue(currentName)
50		ti.Focus()
51		ti.CharLimit = 100
52		ti.Width = 40
53		theme.StyleTextInput(&ti)
