76	// Update handles input events
77	func (w *WorkspaceInput) Update(msg tea.Msg) (*WorkspaceInput, tea.Cmd) {
78		var cmd tea.Cmd
79	
80		switch msg := msg.(type) {
81		case tea.KeyMsg:
82			switch msg.String() {
83			case "down":
84				w.nextFocus()
85				return w, nil
86	
87			case "up":
88				w.prevFocus()
89				return w, nil
90	
91			case "enter":
92				return w.handleEnter()
93	
94			case "esc":
95				return w, func() tea.Msg {
96					return WorkspaceInputCancelMsg{}
97				}
98			}
99		}
100	
101		// Only update text input if it's focused
102		if w.focusIndex == focusInput {
103			w.input, cmd = w.input.Update(msg)
104		}
105	
106		return w, cmd
107	}
108	
109	// nextFocus moves focus to the next element
110	func (w *WorkspaceInput) nextFocus() {
111		w.focusIndex++
112		if w.focusIndex > focusCancel {
113			w.focusIndex = focusInput
114		}
115		w.updateInputFocus()
116	}
117	
118	// prevFocus moves focus to the previous element
119	func (w *WorkspaceInput) prevFocus() {
120		w.focusIndex--
121		if w.focusIndex < focusInput {
122			w.focusIndex = focusCancel
123		}
124		w.updateInputFocus()
125	}
126	
127	// updateInputFocus updates the text input focus state
128	func (w *WorkspaceInput) updateInputFocus() {
129		if w.focusIndex == focusInput {
130			w.input.Focus()
131		} else {
132			w.input.Blur()
133		}
134	}
135	
136	// handleEnter processes enter key based on current focus
137	func (w *WorkspaceInput) handleEnter() (*WorkspaceInput, tea.Cmd) {
138		switch w.focusIndex {
139		case focusInput, focusCreate:
140			name := strings.TrimSpace(w.input.Value())
141			if name != "" {
142				if w.isRename {
143					return w, func() tea.Msg {
144						return RenameInputSubmitMsg{Name: name}
145					}
146				}
147				return w, func() tea.Msg {
148					return WorkspaceInputSubmitMsg{Name: name}
149				}
150			}
151			return w, nil
152	
153		case focusCancel:
154			return w, func() tea.Msg {
155				return WorkspaceInputCancelMsg{}
156			}
157		}
158	
159		return w, nil
160	}
