package workspaces

import "testing"

func TestMatchFuzzySubsequence(t *testing.T) {
	tests := []struct {
		candidate string
		query     string
		want      bool
	}{
		{"devdesk", "dvd", true},
		{"devdesk", "ddk", true},
		{"devdesk", "devdesk", true},
		{"devdesk", "xyz", false},
		{"devdesk", "kdd", false}, // out of order
		{"workspaces/devdesk", "wsd", true},
		{"devdesk", "", false},
	}
	for _, tt := range tests {
		_, got := matchFuzzy(tt.candidate, tt.query)
		if got != tt.want {
			t.Errorf("matchFuzzy(%q, %q) matched = %v, want %v", tt.candidate, tt.query, got, tt.want)
		}
	}
}

func TestMatchFuzzyCaseInsensitive(t *testing.T) {
	if _, ok := matchFuzzy("DevDesk", "dvd"); !ok {
		t.Error("matchFuzzy should ignore case")
	}
}

// A run of consecutive matched characters is a tighter match than the same
// letters scattered across the candidate, and should score higher.
func TestMatchFuzzyScoresConsecutiveRunsHigher(t *testing.T) {
	consecutive, ok := matchFuzzy("abcxyz", "abc")
	if !ok {
		t.Fatal("expected a match")
	}
	scattered, ok := matchFuzzy("axbxcx", "abc")
	if !ok {
		t.Fatal("expected a match")
	}
	if consecutive <= scattered {
		t.Errorf("consecutive score = %d, scattered score = %d, want consecutive higher", consecutive, scattered)
	}
}

// A match starting right after a path separator reads as "this segment",
// which is what a directory jump is usually after — it should outscore the
// same letters matched mid-segment.
func TestMatchFuzzyScoresSegmentBoundaryHigher(t *testing.T) {
	boundary, ok := matchFuzzy("x/bar", "bar")
	if !ok {
		t.Fatal("expected a match")
	}
	midword, ok := matchFuzzy("xxbar", "bar")
	if !ok {
		t.Fatal("expected a match")
	}
	if boundary <= midword {
		t.Errorf("boundary score = %d, mid-word score = %d, want boundary higher", boundary, midword)
	}
}

package workspaces

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"
)

func dirSet(paths []string) map[string]bool {
	out := map[string]bool{}
	for _, p := range paths {
		out[p] = true
	}
	return out
}

func TestCollectDirsFindsPlainDirectories(t *testing.T) {
	root := t.TempDir()
	nested := filepath.Join(root, "a", "b")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatalf("creating the tree: %v", err)
	}

	found := collectDirs(root, false)
	dirs := dirSet(found.Dirs)
	for _, want := range []string{root, filepath.Join(root, "a"), nested} {
		if !dirs[want] {
			t.Errorf("collectDirs(%q) = %v, want %q present", root, found.Dirs, want)
		}
	}
}

// A repository's own tree is not a fuzzy-find target, mirroring
// detectSubRepos's boundary: what stops the walk is finding a repository,
// not a depth limit.
func TestCollectDirsStopsAtRepoBoundary(t *testing.T) {
	root := t.TempDir()
	repo := mkRepoAt(t, root, "repo")
	if err := os.MkdirAll(filepath.Join(repo, "src"), 0o755); err != nil {
		t.Fatalf("creating the repo's own tree: %v", err)
	}

	found := collectDirs(root, false)
	dirs := dirSet(found.Dirs)
	if !dirs[repo] {
		t.Errorf("collectDirs(%q) = %v, want the repository itself present", root, found.Dirs)
	}
	if dirs[filepath.Join(repo, "src")] {
		t.Errorf("collectDirs(%q) = %v, walked inside the repository", root, found.Dirs)
	}
}

func TestCollectDirsRespectsShowHidden(t *testing.T) {
	root := t.TempDir()
	hidden := filepath.Join(root, ".cache")
	if err := os.MkdirAll(hidden, 0o755); err != nil {
		t.Fatalf("creating the hidden directory: %v", err)
	}

	if dirs := dirSet(collectDirs(root, false).Dirs); dirs[hidden] {
		t.Errorf("collectDirs with showHidden=false included %q", hidden)
	}
	if dirs := dirSet(collectDirs(root, true).Dirs); !dirs[hidden] {
		t.Errorf("collectDirs with showHidden=true left out %q", hidden)
	}
}

// The cycle guard walkSubRepos already relies on (mayFollow) is shared by
// this walk, not reimplemented — this is what confirms it actually is.
func TestCollectDirsDoesNotLoopThroughALink(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "a"), 0o755); err != nil {
		t.Fatalf("creating the tree: %v", err)
	}
	linkDir(t, root, filepath.Join(root, "a", "loop"))

	found := collectDirs(root, false)
	for _, p := range found.Dirs {
		if filepath.Base(p) == "loop" {
			t.Fatalf("the walk went through the loop and reported %q", p)
		}
	}
}

func TestCollectDirsCountsUnreadableDirectories(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("chmod does not restrict directory reads on Windows")
	}
	root := t.TempDir()
	closed := filepath.Join(root, "closed")
	if err := os.MkdirAll(closed, 0o755); err != nil {
		t.Fatalf("creating the directory: %v", err)
	}
	if err := os.Chmod(closed, 0o000); err != nil {
		t.Fatalf("closing the directory: %v", err)
	}
	t.Cleanup(func() { _ = os.Chmod(closed, 0o755) })

	found := collectDirs(root, false)
	if found.Skipped != 1 {
		t.Errorf("Skipped = %d, want 1", found.Skipped)
	}
}

package workspaces

import (
	"path/filepath"
	"reflect"
	"testing"
)

// jumpToPath is pure state synthesis (loadEntries' Cmd is not exercised
// here): these tests check what navigateIn would have built one step at a
// time, computed in one shot instead.
func TestJumpToPathSynthesizesDrillDownState(t *testing.T) {
	root := "/tmp/workspaces"

	tests := []struct {
		name            string
		target          string
		wantCurrentPath string
		wantStack       []string
	}{
		{
			name:            "directly under the root",
			target:          filepath.Join(root, "a"),
			wantCurrentPath: "",
			wantStack:       nil,
		},
		{
			name:            "one level nested",
			target:          filepath.Join(root, "a", "b"),
			wantCurrentPath: filepath.Join(root, "a"),
			wantStack:       []string{},
		},
		{
			name:            "two levels nested",
			target:          filepath.Join(root, "a", "b", "c"),
			wantCurrentPath: filepath.Join(root, "a", "b"),
			wantStack:       []string{filepath.Join(root, "a")},
		},
		{
			name:            "three levels nested",
			target:          filepath.Join(root, "a", "b", "c", "d"),
			wantCurrentPath: filepath.Join(root, "a", "b", "c"),
			wantStack:       []string{filepath.Join(root, "a"), filepath.Join(root, "a", "b")},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			m := newTestModel(t)
			next, _ := m.jumpToPath(tt.target)
			got, ok := next.(Model)
			if !ok {
				t.Fatalf("jumpToPath returned %T, want workspaces.Model", next)
			}
			if got.currentPath != tt.wantCurrentPath {
				t.Errorf("currentPath = %q, want %q", got.currentPath, tt.wantCurrentPath)
			}
			if !reflect.DeepEqual(got.navigationStack, tt.wantStack) && len(got.navigationStack) != len(tt.wantStack) {
				t.Errorf("navigationStack = %v, want %v", got.navigationStack, tt.wantStack)
			}
			if got.pendingSelectPath != tt.target {
				t.Errorf("pendingSelectPath = %q, want %q", got.pendingSelectPath, tt.target)
			}
			if len(got.cursorStack) != len(tt.wantStack) {
				t.Errorf("cursorStack = %v, want %d zero-valued entries", got.cursorStack, len(tt.wantStack))
			}
		})
	}
}

// A target outside the workspaces root has no ancestor chain leading back to
// it — the jump is refused rather than climbing to the filesystem root.
func TestJumpToPathRefusesATargetOutsideTheRoot(t *testing.T) {
	m := newTestModel(t)
	before := m

	next, cmd := m.jumpToPath(filepath.Join(filepath.VolumeName(before.getExpandedWorkspacesDir()), "elsewhere", "target"))
	got, ok := next.(Model)
	if !ok {
		t.Fatalf("jumpToPath returned %T, want workspaces.Model", next)
	}
	if got.currentPath != before.currentPath || !reflect.DeepEqual(got.navigationStack, before.navigationStack) {
		t.Errorf("jumpToPath changed navigation state for a target outside the root: currentPath=%q navigationStack=%v", got.currentPath, got.navigationStack)
	}
	if cmd != nil {
		t.Error("jumpToPath returned a Cmd for a target outside the root, want nil")
	}
}

